      const userMetadata = payload.user_metadata || {};
      const appMetadata = payload.app_metadata || {};
      const email = payload.email || userMetadata.email || params.get('email') || "aspirant@clockee.app";
      const name = userMetadata.full_name || userMetadata.name || userMetadata.user_name || email.split('@')[0];
